nextflow_process {

    name "Test Process EPANG_PLACE"
    script "../main.nf"
    process "EPANG_PLACE"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "epang"
    tag "epang/place"

    test("test-epang-place") {

        when {
            process {
                """
                input[0] = [
				    [ id:'test', model:'LG' ], // meta map
				    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/query.alnfaa.gz', checkIfExists: true),
				    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/reference.alnfaa.gz', checkIfExists: true),
				    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/reference.newick', checkIfExists: true)
				]
				input[1] = []
				input[2] = []

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.epang }, // The entire folder including .command.sh, etc
                { assert snapshot(
					file(process.out.jplace[0][1]).name,
					file(process.out.log[0]).name,
					process.out.findAll { key, val -> key.startsWith('versions') }
					).match()
				}
            )
        }
    }

    // EPA-NG reads a gzipped MSA natively -- the query and reference above are already
    // gzipped -- but not a gzipped tree, which aborts with "Treeparsing failed!". The module
    // decompresses that one input.
    test("test-epang-place - gzipped reference tree") {

        when {
            process {
                """
                def gzipped = java.nio.file.Files.createTempDirectory('epang_tree_gz').resolve('reference.newick.gz')
                new java.util.zip.GZIPOutputStream(gzipped.toFile().newOutputStream()).withStream { out ->
                    out << file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/reference.newick', checkIfExists: true).bytes
                }

                input[0] = [
                    [ id:'test', model:'LG' ],
                    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/query.alnfaa.gz', checkIfExists: true),
                    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/reference.alnfaa.gz', checkIfExists: true),
                    file(gzipped.toString())
                ]
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    file(process.out.jplace[0][1]).name,
                    file(process.out.log[0]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                }
            )
        }
    }

    test("test-epang-place-stub") {
        options '-stub'

        when {
            process {
                """
                input[0] = [
				    [ id:'test', model:'LG' ], // meta map
				    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/query.alnfaa.gz', checkIfExists: true),
				    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/reference.alnfaa.gz', checkIfExists: true),
				    file('https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/epang/reference.newick', checkIfExists: true)
				]
				input[1] = []
				input[2] = []

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.epang }, // The entire folder including .command.sh, etc
                { assert snapshot(
                    process.out.jplace,
					file(process.out.log[0]).name,
					process.out.findAll { key, val -> key.startsWith('versions') }
					).match()
				}
            )
        }
    }

}

process {
    // This is a very clear techniuqe to pass sample specific optional value arguments.
    // I do not think this violates any nf-core guidelines
    ext.args   = { " --model ${meta.model} " }
}
